/* Roomie prototype: all names, memberships and messages are fictional demo data. */
const KEY='roomie-ra-prototype-v2';const defaults={role:'student',name:'Alex Morgan',building:'Morgens Hall',floor:'9',room:'904',chores:[{id:1,title:'Take out the trash',who:'Alex Morgan',due:'Today',done:false},{id:2,title:'Clean bathroom',who:'Jordan Lee',due:'Tomorrow',done:false},{id:3,title:'Vacuum the room',who:'Alex Morgan',due:'Friday',done:true}],expenses:[{id:1,title:'Cleaning supplies',amount:24,who:'Alex Morgan',paid:false},{id:2,title:'Paper towels',amount:16,who:'Jordan Lee',paid:true}],reports:[{id:1,room:'904',title:'Sink dripping',description:'Bathroom sink has been dripping since yesterday.',status:'Open',type:'Maintenance'},{id:2,room:'902',title:'Quiet hours question',description:'Need clarification on weekend quiet hours.',status:'In progress',type:'Question'},{id:3,room:'906',title:'Shared kitchen light',description:'Light in common area needs replacing.',status:'Open',type:'Maintenance'}],roomMessages:[],messages:[{who:'RA Samara',text:'Hey! Just checking in. Let me know if anything comes up.',mine:false},{who:'Alex',text:'Thanks! Is there a floor meeting this week?',mine:true},{who:'RA Samara',text:'Yes — Thursday at 7 PM in the lounge!',mine:false}],announcements:[{title:'Floor meeting Thursday',body:'Join us in the 9th-floor lounge at 7 PM.'},{title:'Quiet hours reminder',body:'Please keep shared spaces respectful during study hours.'}],rules:['Quiet hours begin at 10 PM on weekdays','Clean up shared areas after use','Ask before having overnight guests'],selectedRoom:'904'};
let state;try{state={...structuredClone(defaults),...JSON.parse(localStorage.getItem(KEY)||'{}')}}catch{state=structuredClone(defaults)};const save=()=>localStorage.setItem(KEY,JSON.stringify(state));const qs=new URLSearchParams(location.search);let screen=qs.get('screen')||'welcome';const id=x=>document.getElementById(x);const escapeHTML=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const initials=s=>s.split(' ').map(n=>n[0]).join('').slice(0,2).toUpperCase();const panel=(title,body,action='')=>`<section class="panel"><div class="between"><h2>${title}</h2>${action}</div>${body}</section>`;function toast(msg){const el=document.createElement('div');el.className='toast';el.textContent=msg;document.body.append(el);setTimeout(()=>el.remove(),2700)}function go(s){screen=s;history.pushState({screen:s},'',`?screen=${s}`);render();scrollTo(0,0)}window.addEventListener('popstate',()=>{screen=new URLSearchParams(location.search).get('screen')||'welcome';render()});const navs=[['dashboard','⌂','Dashboard'],['roommates','♙','My room'],['chores','☑','Chores'],['expenses','▤','Expenses'],['contact','✉','Messages & reports'],['ra-dashboard','▦','RA dashboard'],['ra-rooms','▣','Managed rooms']];function sidebar(){return `<aside class="side"><div class="brand"><span class="brand-mark">⌂</span><div>roomie<small>Campus living</small></div></div><div class="nav"><div class="navlabel">YOUR SPACE</div><button onclick="go('join')"><span class="ico">＋</span>Join a room</button>${navs.slice(0,5).map(([s,i,n])=>`<button class="${screen===s?'active':''}" onclick="go('${s}')"><span class="ico">${i}</span>${n}</button>`).join('')}<div class="navlabel" style="margin-top:26px">RESIDENT ASSISTANT</div>${navs.slice(5).map(([s,i,n])=>`<button class="${screen===s?'active':''}" onclick="go('${s}')"><span class="ico">${i}</span>${n}</button>`).join('')}</div><div class="sidefoot"><strong>⌂ Morgens Hall · Floor 9</strong>Room ${escapeHTML(state.room)} · Demo workspace<br><button class="link" onclick="go('account')">Switch account / role ↗</button></div></aside>`}function layout(content,title,subtitle){return `<div class="app">${sidebar()}<main class="main"><div class="prototype-banner"><span>INTERACTIVE PROTOTYPE · Fictional residents · Changes saved on this device only</span><div><button class="link" onclick="localStorage.removeItem(KEY);location.reload()">Reset demo</button> · <a href="/">Back to Roomie ↗</a></div></div><header class="top"><span class="crumb">Roomie / ${escapeHTML(title)}</span><div class="top-right"><span class="bell">♧</span><span>${escapeHTML(state.name)} <span class="muted">· ${screen.startsWith('ra-')?'RA demo':state.role==='ra'?'RA demo':'Student demo'}</span></span><div class="avatar">${escapeHTML(initials(state.name))}</div></div></header><h1 class="heading">${title}</h1><p class="sub">${subtitle}</p>${content}</main><nav class="mobile-nav">${navs.slice(0,5).map(([s,i])=>`<button onclick="go('${s}')">${i}</button>`).join('')}</nav></div>`}function listRow(icon,title,desc,right){return `<div class="listrow"><div class="row"><span class="roundIcon">${icon}</span><div><div class="rowtitle">${title}</div><div class="rowdesc">${desc}</div></div></div>${right||''}</div>`}function dashboard(){return layout(`<div class="hero"><div><div class="small" style="opacity:.8">MORGENS HALL · FLOOR 9</div><h2>Welcome home, ${escapeHTML(state.name.split(' ')[0])}! 👋</h2><p>Everything you and your roommates need to stay organized, all in one place.</p><button class="secondary" onclick="go('roommates')">Explore your room →</button></div><div class="hero-graphic">⌂</div></div><div class="grid3" style="margin-bottom:22px">${[['☑',state.chores.filter(x=>!x.done).length,'Open chores'],['＄','$'+state.expenses.filter(x=>!x.paid).reduce((a,x)=>a+x.amount/2,0).toFixed(2),'Your unpaid share'],['✉',state.reports.filter(x=>x.room===state.room&&x.status!=='Resolved').length,'Your open reports']].map(([ico,n,label])=>`<section class="panel stat"><div class="symbol">${ico}</div><div class="num">${n}</div><div class="label">${label}</div></section>`).join('')}</div><div class="columns"><div class="stack">${panel('Upcoming chores',state.chores.slice(0,3).map(x=>listRow(x.done?'✓':'☐',escapeHTML(x.title),`${escapeHTML(x.who)} · ${x.due}`,`<span class="pill ${x.done?'green':'orange'}">${x.done?'Done':'To do'}</span>`)).join(''),`<button class="link" onclick="go('chores')">See all →</button>`)}${panel('Latest floor announcements',state.announcements.map(x=>listRow('📣',escapeHTML(x.title),escapeHTML(x.body),'<span class="pill">Floor 9</span>')).join(''))}</div><div class="stack">${panel('Your room',`<div class="between"><div><div class="muted small">Morgens Hall · Floor 9</div><div style="font:800 37px Outfit;margin:7px 0">Room ${escapeHTML(state.room)}</div><span class="pill green">● Connected</span></div><div style="font-size:65px">🛋️</div></div><hr style="border:0;border-top:1px solid #edf0f6;margin:20px 0"><div class="between"><div class="row"><div class="avatar">AM</div><div class="avatar" style="background:#ffeadc;color:#d27e39">JL</div></div><button class="link" onclick="go('roommates')">View room →</button></div>`)}${panel('Your resident assistant',`<div class="row"><div class="avatar" style="background:#dcf5ed;color:#248969">SC</div><div><strong>Samara Chatrath</strong><div class="rowdesc">RA · Morgens Floor 9</div></div></div><button class="primary" style="width:100%;margin-top:20px" onclick="go('contact')">✉ Message your RA</button>`)}</div></div>`,'Your dashboard','A quick look at your room, tasks, and community updates.')}
function welcome(){return `<div class="welcome"><div class="welcomeLeft"><div class="brand" style="padding:0"><span class="brand-mark">⌂</span>roomie</div><div class="loginBox"><span class="pill">CAMPUS LIVING, SIMPLIFIED</span><h1>Your space.<br>Your people.<br>All together.</h1><p>Stay on top of chores, split shared expenses, and connect with your resident assistant — all in one place.</p><div class="stack" style="margin-top:27px"><label class="field">School email<input type="email" id="email" placeholder="name@university.edu"/></label><label class="field">Password<input id="password" type="password" placeholder="••••••••"/></label><button class="primary" onclick="go('account')">Continue to Roomie →</button><div class="small muted">Prototype demo — choose an account type on the next screen. This login is not connected to a server.</div></div></div><div class="muted small">© 2026 Roomie · Student project prototype</div></div><div class="welcomeRight"><div class="showcard"><div class="emoji">🏠</div><h2>Make room for better living.</h2><p>Everything your dorm community needs in one beautiful space.</p><div class="msg">☑ &nbsp; Take out the trash &nbsp; <span class="pill green">Complete</span></div><div class="msg" style="margin-top:12px">💬 &nbsp; RA message received &nbsp; <span class="pill">New</span></div></div></div></div>`}
function account(){return layout(`<div class="columns"><div class="stack">${panel('Choose your account type',`<p class="muted small">Student accounts manage a room. RA accounts oversee assigned rooms, announcements, and reports.</p><div class="row" style="margin:17px 0"><button class="option ${state.role==='student'?'selected':''}" onclick="state.role='student';save();render()"><div style="font-size:27px">🎓</div><strong>Student</strong><span>Try the student experience</span></button><button class="option ${state.role==='ra'?'selected':''}" onclick="state.role='ra';save();render()"><div style="font-size:27px">🗝️</div><strong>Resident Assistant</strong><span>Try the RA experience</span></button></div><div class="formgrid"><label class="field">Display name<input id="displayname" value="${escapeHTML(state.name)}"/></label><label class="field">Building<select id="building"><option>Morgens Hall</option></select></label></div><div style="margin-top:17px" class="formgrid"><label class="field">Floor<select id="floor"><option>9</option></select></label><label class="field">${state.role==='ra'?'RA assignment code':'Room number'}<input maxlength="16" id="roomnumber" value="${state.role==='ra'?'DEMO-RA-9':escapeHTML(state.room)}" /></label></div><div style="margin-top:22px"><button class="primary" onclick="saveAccount()">${state.role==='ra'?'Open RA dashboard':'Join your room'} →</button></div>`)} </div><div class="stack">${panel('How Roomie works',listRow('1','Create an account','Select student or RA role')+listRow('2','Join your community','Connect to a building, floor and room')+listRow('3','Stay in sync','Manage tasks and message your RA'))}<div class="notice">🔒 In a real deployment, RA access must be verified and assigned by authorized university housing staff. Selecting “RA” here enables demo access only.</div></div></div>`,'Set up your account','Get connected to your room or residential community.')}
function saveAccount(){state.name=id('displayname').value.trim()||state.name;state.building=id('building').value;state.floor=id('floor').value;if(state.role==='student')state.room=id('roomnumber').value.trim()||'904';if(state.role==='student'&&!demoRooms.includes(state.room))return toast('Choose a demo room from 901 to 912');save();go(state.role==='ra'?'ra-dashboard':'join');toast('Demo profile updated')}
function join(){return layout(`${panel('Your housing assignment',`<div class="grid3"><div><div class="small muted">Building</div><h2>Morgens Hall</h2></div><div><div class="small muted">Floor</div><h2>9</h2></div><div><div class="small muted">Room</div><h2>${escapeHTML(state.room)}</h2></div></div>`)}<div style="height:20px"></div>${panel('Join another room',`<div class="formgrid"><label class="field">Room number<input id="joinroom" placeholder="e.g. 904" value="${escapeHTML(state.room)}"/></label><label class="field">Invite code<input id="invite" placeholder="Optional demo code"/></label></div><button class="primary" style="margin-top:20px" onclick="joinDemoRoom()">Join room</button>`)} `,'Join your room','Connect to the right roommates and resident assistant.')}
function roommates(){return layout(`<div class="hero"><div><div class="small">MORGENS HALL · FLOOR 9</div><h2>Room ${escapeHTML(state.room)}</h2><p>Your shared home base for roommates, expectations, and updates.</p><button class="secondary" onclick="go('join')">Change room →</button></div><div class="hero-graphic">🛋️</div></div><div class="columns"><div class="stack">${panel('Room members',listRow('👤','Alex Morgan','Room member · Student','<span class="pill green">Active</span>')+listRow('👤','Jordan Lee','Room member · Student','<span class="pill green">Active</span>'),`<button class="link" onclick="toast('Demo invitation copied: ROOM-${state.room}')">+ Invite roommate</button>`)}${panel('Our house rules',state.rules.map((r,i)=>listRow('📌',escapeHTML(r),`Rule ${i+1}`,'<span class="pill">Agreed</span>')).join(''),`<button class="link" onclick="const v=prompt('Add a house rule');if(v){state.rules.push(v);save();render()}">+ Add rule</button>`)}</div><div class="stack">${panel('Room at a glance',`<div class="stat" style="padding:5px"><div class="num">${state.chores.filter(x=>x.done).length} / ${state.chores.length}</div><div class="label">Chores completed</div><div class="bar" style="margin:15px 0"><i style="width:${100*state.chores.filter(x=>x.done).length/state.chores.length}%"></i></div><button class="secondary" onclick="go('chores')">Manage chores</button></div>`)}${panel('Resident assistant',`<div class="row"><div class="avatar">SC</div><div><b>Samara Chatrath</b><div class="rowdesc">Assigned RA, Floor 9</div></div></div><button class="primary" style="width:100%;margin-top:22px" onclick="go('contact')">Contact RA →</button>`)}</div></div>`,'My room','Your roommates, shared rules, and dorm connections.')}
function chores(){return layout(`<div class="grid3" style="margin-bottom:22px">${[['Total tasks',state.chores.length],['Completed',state.chores.filter(x=>x.done).length],['To do',state.chores.filter(x=>!x.done).length]].map(([l,n])=>`<div class="panel stat"><div class="num">${n}</div><div class="label">${l}</div></div>`).join('')}</div><div class="columns">${panel('Shared chore checklist',state.chores.map(c=>`<div class="listrow"><div class="row"><input aria-label="Complete ${escapeHTML(c.title)}" class="check" type="checkbox" ${c.done?'checked':''} onchange="toggleChore(${c.id})"/><div><div class="rowtitle" style="${c.done?'text-decoration:line-through;opacity:.6':''}">${escapeHTML(c.title)}</div><div class="rowdesc">Assigned to ${escapeHTML(c.who)} · ${c.due}</div></div></div><span class="pill ${c.done?'green':'orange'}">${c.done?'Completed':'Pending'}</span></div>`).join(''))}${panel('Add a chore',`<div class="stack"><label class="field">Task name<input id="choretitle" placeholder="e.g. Take out recycling"/></label><label class="field">Assign to<select id="chorewho"><option>Alex Morgan</option><option>Jordan Lee</option></select></label><label class="field">Due<select id="choredue"><option>Today</option><option>Tomorrow</option><option>Friday</option><option>Next week</option></select></label><button class="primary" onclick="addChore()">+ Add chore</button></div>`)}</div>`,'Chore manager','Keep your room clean without the arguments.');}function toggleChore(cid){state.chores=state.chores.map(x=>x.id===cid?{...x,done:!x.done}:x);save();render()}function addChore(){const t=id('choretitle').value.trim();if(!t)return toast('Enter a task name');state.chores.push({id:Date.now(),title:t,who:id('chorewho').value,due:id('choredue').value,done:false});save();render();toast('Chore added')}
function expenses(){const total=state.expenses.reduce((s,x)=>s+x.amount,0),unpaid=state.expenses.filter(x=>!x.paid).reduce((s,x)=>s+x.amount/2,0);return layout(`<div class="grid3" style="margin-bottom:23px">${[['Total shared','$'+total.toFixed(2)],['Your share','$'+(total/2).toFixed(2)],['Unpaid share','$'+unpaid.toFixed(2)]].map(([l,n])=>`<section class="panel stat"><div class="symbol">＄</div><div class="num">${n}</div><div class="label">${l}</div></section>`).join('')}</div><div class="columns">${panel('Shared expenses',state.expenses.map(x=>listRow('💳',escapeHTML(x.title),`Added by ${escapeHTML(x.who)} · Split 50/50`,`<div style="text-align:right"><b>$${x.amount.toFixed(2)}</b><br><button class="link" onclick="toggleExpense(${x.id})">${x.paid?'✓ Paid':'Mark paid'}</button></div>`)).join('')+`<div class="notice" style="margin-top:15px">Roomie only tracks expenses in this demo; no actual payments are processed.</div>`)}${panel('Add an expense',`<div class="stack"><label class="field">Description<input id="expensename" placeholder="e.g. Laundry detergent"/></label><label class="field">Amount ($)<input id="expenseamount" type="number" min="0.01" step="0.01" placeholder="12.00"/></label><button class="primary" onclick="addExpense()">+ Add expense</button></div>`)}</div>`,'Shared expenses','Split common costs and keep everyone on the same page.')}function addExpense(){const t=id('expensename').value.trim(),v=Number(id('expenseamount').value);if(!t||!Number.isFinite(v)||v<=0)return toast('Enter an expense and positive amount');state.expenses.push({id:Date.now(),title:t,amount:v,who:state.name,paid:false});save();render();toast('Expense added')}function toggleExpense(i){state.expenses=state.expenses.map(x=>x.id===i?{...x,paid:!x.paid}:x);save();render()}
function contact(){return layout(`<div class="columns"><div class="stack">${panel('Message your RA',`<div class="row" style="margin-bottom:17px"><div class="avatar">SC</div><div><strong>Samara Chatrath</strong><div class="rowdesc">Resident Assistant · Floor 9</div></div><span class="pill green" style="margin-left:auto">Assigned RA</span></div><div class="chatbox">${[...state.messages,...state.roomMessages.filter(x=>x.room===state.room)].map(x=>`<div class="bubble ${x.mine?'me':''}">${escapeHTML(x.text)}<small>${escapeHTML(x.who)}</small></div>`).join('')}</div><div class="row"><input id="chattext" style="flex:1;padding:13px;border:1px solid #e5e8f0;border-radius:12px" placeholder="Type a message..." onkeydown="if(event.key==='Enter')sendMessage()"/><button class="primary" onclick="sendMessage()">Send ↗</button></div>`)} </div><div class="stack">${panel('Submit an issue',`<div class="stack"><label class="field">Issue type<select id="reporttype"><option>Maintenance</option><option>Roommate concern</option><option>Question</option><option>Other</option></select></label><label class="field">Subject<input id="reporttitle" placeholder="Briefly describe the issue"/></label><label class="field">Details<textarea id="reportdesc" placeholder="What happened? What help do you need?"></textarea></label><button class="primary" onclick="addReport()">Submit to RA</button></div>`)}${panel('Your submitted reports',state.reports.filter(r=>r.room===state.room).map(x=>listRow('📋',escapeHTML(x.title),escapeHTML(x.type),`<span class="pill ${x.status==='Resolved'?'green':'orange'}">${x.status}</span>`)).join(''))}</div></div>`,'Messages & reports','Reach your RA directly and report concerns when needed.')}function sendMessage(){const t=id('chattext').value.trim();if(!t)return;state.messages.push({who:state.name.split(' ')[0],text:t,mine:true});save();render();toast('Demo message saved locally')}function addReport(){let title=id('reporttitle').value.trim();if(!title)return toast('Add a subject first');state.reports.unshift({id:Date.now(),room:state.room,title,description:id('reportdesc').value.trim(),status:'Open',type:id('reporttype').value});save();render();toast('Report submitted to demo RA inbox')}
function raDashboard(){return layout(`<div class="hero"><div><div class="small">RESIDENT ASSISTANT PORTAL</div><h2>Your floor, connected.</h2><p>Your Morgens Hall Floor 9 community at a glance. Keep residents connected, informed, and supported.</p><button class="secondary" onclick="go('ra-rooms')">Manage your rooms →</button></div><div class="hero-graphic">🏢</div></div><div class="grid3" style="margin-bottom:23px">${[['🏠','12','Assigned rooms'],['♙','24','Residents (demo)'],['📋',state.reports.filter(x=>x.status!=='Resolved').length,'Open reports']].map(([ico,num,l])=>`<section class="panel stat"><div class="symbol">${ico}</div><div class="num">${num}</div><div class="label">${l}</div></section>`).join('')}</div><div class="columns"><div class="stack">${panel('Resident reports',state.reports.slice(0,4).map(x=>listRow('📋',escapeHTML(x.title),`Room ${x.room} · ${escapeHTML(x.type)}`,`<span class="pill ${x.status==='Resolved'?'green':'orange'}">${x.status}</span>`)).join(''),`<button class="link" onclick="go('ra-rooms')">Manage reports →</button>`)}${panel('Floor announcements',state.announcements.map(x=>listRow('📣',escapeHTML(x.title),escapeHTML(x.body))).join(''))}</div><div class="stack">${panel('Your assigned community',`<div class="row"><span class="roundIcon">🏢</span><div><b>Morgens Hall</b><div class="rowdesc">Floor 9 · 12 managed rooms</div></div></div><div class="bar" style="margin:21px 0"><i style="width:72%"></i></div><button class="primary" style="width:100%" onclick="go('ra-rooms')">View managed rooms</button>`)}${panel('Post an announcement',`<div class="stack"><label class="field">Title<input id="announcementtitle" placeholder="e.g. Floor meeting"/></label><label class="field">Message<textarea id="announcementbody" placeholder="Share an update with your floor..."></textarea></label><button class="primary" onclick="addAnnouncement()">Post to Floor 9 →</button></div>`)}</div></div>`,'RA dashboard','Manage your floor and respond to resident needs.')}function addAnnouncement(){let title=id('announcementtitle').value.trim(),body=id('announcementbody').value.trim();if(!title||!body)return toast('Enter title and message');state.announcements.unshift({title,body});save();render();toast('Announcement posted in demo')}
const demoRooms=['901','902','903','904','905','906','907','908','909','910','911','912'];function raRooms(){return layout(`<div class="between" style="margin-bottom:22px"><div class="row"><span class="roundIcon">🏢</span><div><strong>Morgens Hall · Floor 9</strong><div class="rowdesc">12 rooms in your authorized demo group</div></div></div><span class="pill green">RA assigned</span></div><div class="roomgrid" style="margin-bottom:25px">${demoRooms.map(r=>`<button class="roomtile" onclick="state.selectedRoom='${r}';save();go('ra-room-detail')"><div style="font-size:27px">🚪</div><strong>Room ${r}</strong><small>2 residents · Floor 9</small><br><span class="pill ${state.reports.some(x=>x.room===r&&x.status!=='Resolved')?'orange':'green'}">${state.reports.some(x=>x.room===r&&x.status!=='Resolved')?'Issue reported':'No open issues'}</span></button>`).join('')}</div>${panel('Floor-wide announcements',state.announcements.map(x=>listRow('📣',escapeHTML(x.title),escapeHTML(x.body))).join(''),`<button class="link" onclick="go('ra-dashboard')">Create announcement →</button>`)}`,'Managed rooms','Every room in your assigned RA group, organized in one place.')}
function raDetail(){let r=state.selectedRoom||'904',reports=state.reports.filter(x=>x.room===r);return layout(`<div class="between" style="margin-bottom:22px"><button class="secondary" onclick="go('ra-rooms')">← Back to all rooms</button><span class="pill">Morgens Hall · Floor 9</span></div><div class="hero"><div><div class="small">ROOM PROFILE</div><h2>Room ${escapeHTML(r)}</h2><p>Review issues submitted to you and message the residents of this room.</p></div><div class="hero-graphic">🚪</div></div><div class="columns"><div class="stack">${panel('Residents',listRow('👤',r==='904'?'Alex Morgan':'Taylor Brooks','Resident · Student','<span class="pill green">Active</span>')+listRow('👤',r==='904'?'Jordan Lee':'Casey Rivera','Resident · Student','<span class="pill green">Active</span>'))}${panel('Submitted reports',reports.length?reports.map(x=>`<div class="listrow"><div><div class="rowtitle">${escapeHTML(x.title)}</div><div class="rowdesc">${escapeHTML(x.description||x.type)}</div></div><select aria-label="Status for ${escapeHTML(x.title)}" onchange="changeStatus(${x.id},this.value)" style="padding:10px;border:1px solid #e2e5ee;border-radius:11px"><option ${x.status==='Open'?'selected':''}>Open</option><option ${x.status==='In progress'?'selected':''}>In progress</option><option ${x.status==='Resolved'?'selected':''}>Resolved</option></select></div>`).join(''):`<p class="muted small">There are no reports for this room.</p>`)}</div><div class="stack">${panel('Room information',listRow('🏢','Morgens Hall','Building')+listRow('▦','Floor 9','Assigned RA group')+listRow('🗝️','Samara Chatrath','Resident assistant'))}${panel('Contact residents',`<p class="muted small">Send a floor update or follow up on a report. In this prototype, messages are stored locally.</p><textarea id="roommessage" style="width:100%;min-height:95px;border-radius:12px;border:1px solid #e5e6ef;padding:12px" placeholder="Write a message to Room ${r}..."></textarea><button class="primary" style="margin-top:12px" onclick="sendRoomMessage('${r}')">Send message →</button>`)}</div></div>`,'Room '+r+' details','Resident information, communication, and issue tracking.')}function changeStatus(i,value){state.reports=state.reports.map(x=>x.id===i?{...x,status:value}:x);save();render();toast('Report status updated')}
function joinDemoRoom(){const room=id('joinroom').value.trim();if(!demoRooms.includes(room))return toast('Choose a demo room from 901 to 912');state.room=room;save();go('roommates');toast('Joined demo room '+room)}
function sendRoomMessage(room){const text=id('roommessage').value.trim();if(!text)return toast('Enter a message');state.roomMessages.push({room,who:'Demo RA',text,mine:false});save();id('roommessage').value='';toast('Demo message saved to Room '+room+' inbox')}
function render(){document.title='Roomie — '+screen;const views={welcome,account,join,dashboard,roommates,chores,expenses,contact,'ra-dashboard':raDashboard,'ra-rooms':raRooms,'ra-room-detail':raDetail};id('app').innerHTML=(views[screen]||dashboard)()}render();
